def repair_counters(apps, schema_editor):
    """Legacy rows may have free_slots > total_slots; rebuild both from the real slots so the
    new CHECK constraint can be added instead of crashing the deploy."""
    from django.db.models import Count, Q

    lot_model = apps.get_model("parking", "ParkingLot")
    slot_model = apps.get_model("parking", "Slot")
    counts = {
        row["zone__parking_lot"]: row
        for row in slot_model.objects.values("zone__parking_lot").annotate(
            total=Count("id"), free=Count("id", filter=Q(status="FREE"))
        )
    }
    for lot in lot_model.objects.all().iterator():
        row = counts.get(lot.pk, {"total": 0, "free": 0})
        if (lot.total_slots, lot.free_slots) != (row["total"], row["free"]):
            lot_model.objects.filter(pk=lot.pk).update(
                total_slots=row["total"], free_slots=row["free"]
            )


def refuse_negative_prices(apps, schema_editor):
    """Money is never silently rewritten: stop with a clear message and let a human decide."""
    tariff_model = apps.get_model("parking", "Tariff")
    bad = list(tariff_model.objects.filter(price_per_hour__lt=0).values_list("pk", flat=True)[:10])
    if bad:
        raise RuntimeError(
            f"Cannot add tariff_price_non_negative: tariffs with a negative price exist "
            f"(ids: {bad}). Fix or delete them, then migrate again."
        )


